import { useState, forwardRef } from 'react';
import { forwardRef } from 'react';

interface TabItem {
  label: string;
  value: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  badge?: string | number;
}

interface TabsProps {
  tabs: TabItem[];
  value: string;
  onChange: (value: string) => void;
  variant?: 'default' | 'underline' | 'pills';
  className?: string;
  fullWidth?: boolean;
}

export default function Tabs({
  tabs,
  value,
  onChange,
  variant = 'default',
  className = '',
  fullWidth = false,
}: TabsProps) {
  return (
    <div className={className} role="tablist" aria-orientation="horizontal">
      <div
        className={`flex ${fullWidth ? 'w-full' : ''} ${variant === 'underline' ? 'border-b border-white/10' : ''} ${variant === 'pills' ? 'bg-white/5 p-1 rounded-xl' : ''}`}
      >
        {tabs.map((tab, index) => (
          <button
            key={tab.value}
            role="tab"
            aria-selected={value === tab.value}
            aria-controls={`tabpanel-${tab.value}`}
            id={`tab-${tab.value}`}
            onClick={() => !tab.disabled && onChange(tab.value)}
            disabled={tab.disabled}
            className={
              `relative flex flex-col items-center gap-1 px-4 py-3 text-sm font-medium transition-all duration-200 ${
                fullWidth ? 'flex-1' : ''
              } ${
                tab.disabled
                  ? 'opacity-50 cursor-not-allowed text-gray-500'
                  : value === tab.value
                  ? variant === 'pills'
                    ? 'text-violet-300 bg-white/10 rounded-lg shadow-sm'
                    : variant === 'underline'
                    ? 'text-violet-300'
                    : 'text-violet-300 bg-violet-500/10 rounded-t-lg'
                  : 'text-gray-400 hover:text-gray-200 hover:bg-white/5'
              }`}
            tabIndex={value === tab.value ? 0 : -1}
          >
            {tab.icon && <span className="w-4 h-4">{tab.icon}</span>}
            <span className="flex items-center gap-1">{tab.label}</span>
            {tab.badge && (
              <span
                className={`text-xs px-1.5 py-0.5 rounded-full ${value === tab.value ? 'bg-violet-500/30 text-violet-300' : 'bg-white/10 text-gray-400'}`}
              >{tab.badge}</span>
            )}
          </button>
        ))}
        {variant === 'underline' && (
          <div
            className="absolute bottom-0 h-0.5 bg-gradient-to-r from-violet-500 to-cyan-500 transition-all duration-300 ease-out"
            style={{
              width: `${100 / tabs.length}%`,
              transform: `translateX(${tabs.findIndex(t => t.value === value) * (100 / tabs.length)}%)`,
            }}
            aria-hidden="true"
          />
        )}
      </div>
      <div className="mt-4">
        {tabs.map(tab => (
          <div
            key={tab.value}
            role="tabpanel"
            id={`tabpanel-${tab.value}`}
            aria-labelledby={`tab-${tab.value}`}
            hidden={value !== tab.value}
            className="animate-fade-in"
          >
            {value === tab.value && tab.children}
          </div>
        ))}
      </div>
    </div>
  );
}

// Enhanced Tabs with panels built-in
interface TabsWithPanelsProps {
  tabs: (TabItem & { children: React.ReactNode })[];
  defaultValue?: string;
  variant?: 'default' | 'underline' | 'pills';
  className?: string;
  fullWidth?: boolean;
}

export function TabsWithPanels({
  tabs,
  defaultValue = tabs[0]?.value,
  variant = 'default',
  className = '',
  fullWidth = false,
}: TabsWithPanelsProps) {
  const [value, setValue] = useState(defaultValue);

  return (
    <Tabs
      tabs={tabs.map(t => ({ label: t.label, value: t.value, icon: t.icon, disabled: t.disabled, badge: t.badge }))}
      value={value}
      onChange={setValue}
      variant={variant}
      className={className}
      fullWidth={fullWidth}
    >
      {tabs.map(tab => (
        <div key={tab.value} role="tabpanel" id={`tabpanel-${tab.value}`} aria-labelledby={`tab-${tab.value}`} hidden={value !== tab.value}>
          {value === tab.value && tab.children}
        </div>
      ))}
    </Tabs>
  );
}
